/**
 TOML text for catalog-owned values.

 Keys are crate names already validated as bare-key safe; string values are
 written as TOML basic strings through `JSON.stringify`, whose escapes are a
 subset of TOML's.

 @module
 */

import type { RustCatalogEntry, } from '@monochromatic-dev/module-rust-catalog/ts';

//region Values

/**
 Comment above each crate's generated `[workspace.dependencies]` table.
 */
export const GENERATED_TABLE_COMMENT =
  '# Generated by file-enforcer from rust-catalog.toml; edit the catalog, not this table (doc/decision/rust-dependency-catalog.md).';

/**
 Header of the generated table.
 */
export const GENERATED_TABLE_HEADER = '[workspace.dependencies]';

/**
 Renders a TOML basic string.

 @param value - string to encode

 @returns quoted TOML string

 @example
 ```ts
 renderString('>=1.0.104'); // '">=1.0.104"'
 ```
 */
export function renderString(value: string,): string {
  return JSON.stringify(value,);
}

/**
 Renders a catalog entry as the value a manifest's `[workspace.dependencies]` or the catalog itself holds.

 @param entry - catalog entry

 @returns TOML value text

 @example
 ```ts
 renderEntryValue({ kind: 'registry', version: '>=1', }); // '">=1"'
 renderEntryValue({ kind: 'git', git: 'https://x', rev: 'abc', }); // '{ git = "https://x", rev = "abc" }'
 ```
 */
export function renderEntryValue(entry: RustCatalogEntry,): string {
  /**
   Rename suffix, empty without a rename.
   */
  const rename = entry.package === undefined ? '' : `, package = ${renderString(entry.package,)}`;
  if (entry.kind === 'git')
    return `{ git = ${renderString(entry.git,)}, rev = ${renderString(entry.rev,)}${rename} }`;
  if (entry.package === undefined)
    return renderString(entry.version,);
  return `{ version = ${renderString(entry.version,)}${rename} }`;
}

/**
 Renders the generated table body, one entry per line, sorted by name.

 @param entries - dependency name to resolved catalog entry

 @returns header line plus entry lines, each ending in a newline

 @example
 ```ts
 renderGeneratedTable(new Map([['anyhow', { kind: 'registry', version: '>=1', }]]));
 // '[workspace.dependencies]\nanyhow = ">=1"\n'
 ```
 */
export function renderGeneratedTable(entries: ReadonlyMap<string, RustCatalogEntry>,): string {
  /**
   Entry lines in name order.
   */
  const lines = [...entries.entries(),]
    .toSorted(function byName([left,], [right,],): number {
      return left < right ? -1 : (left > right ? 1 : 0);
    },)
    .map(function toLine([name, entry,],): string {
      return `${name} = ${renderEntryValue(entry,)}\n`;
    },);
  return `${GENERATED_TABLE_HEADER}\n${lines.join('',)}`;
}

//endregion Values
